using Sudoku.src.Entities.Models;
using Sudoku.src.Logic;

namespace MySudokuTests._25X25Boards
{
    [TestClass]
    public class Medium25X25Boards
    {
        [TestMethod]
        public void Medium25X25Board1()
        {
            //Arrange
            string expression = "0E003000000000F000<;00000000000000000000:000000000000000000B000000000000G00000000000000000000000000000010000000000000000000000C00000000000000000000200000000000000000000000A000";

            //Act
            Board board = new Board(expression);
            bool solved = BoardSolver.SolveBoard(board);

            //Assert
            Assert.IsTrue(solved);
        }

